import sys


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def lcm(a, b):
    return a * b // gcd(a, b)


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums = [int(x) for x in line.split()]
        if not nums:
            continue
        g = abs(nums[0])
        l = abs(nums[0])
        for n in nums[1:]:
            g = gcd(g, abs(n))
            l = l * abs(n) // gcd(l, abs(n))
        print(g, l)


if __name__ == "__main__":
    main()
